/* --- quais interfaces são links --- */
const WANRX = /^\s*(WAN|LINK|ISP)[\s_\-:]*([^\d\s][^\s]*)?\s*(?:(\d+(?:[.,]\d+)?)\s*([MG])?\s*\/\s*(\d+(?:[.,]\d+)?)\s*([MG])?)?/i;
