.noc .kpi .v span{font-size:13px;color:var(--ink2);font-weight:400}
.noc .kpi .s{font-size:10px;color:var(--mute)}
.noc .kpi.ok{border-left-color:var(--ok)}.noc .kpi.warn{border-left-color:var(--warn)}.noc .kpi.crit{border-left-color:var(--crit)}
