.noc .card.warn{border-top-color:var(--warn)}.noc .card.crit{border-top-color:#fb923c}.noc .card.crit .dot{background:#fb923c}.noc .card.crit .issue{background:rgba(251,146,60,.16);color:#fdba74}
.noc .card.down{border-top-color:var(--crit);background:#1d1418}.noc .card.down .dot{background:var(--crit)}.noc .card.down .issue{background:rgba(239,68,68,.18);color:#fca5a5}
