.noc .chip.warn{border-left-color:var(--warn)}.noc .chip.crit{border-left-color:var(--crit);background:#1d1418}.noc .chip.unk{border-left-color:var(--mute)}
.noc .chip .dot{width:7px;height:7px}.noc .chip.unk .dot{background:var(--mute)}
.noc .chip .sn{font-weight:600}.noc .chip .sm{color:var(--ink2);font-family:Consolas,monospace;font-size:10px}.noc .chip .sm.hot{color:var(--warn);font-weight:700}
.noc .card.maint{border-top-color:#6b7280;opacity:.6}.noc .card.maint .dot{background:#6b7280}
.noc .card.maint .issue{background:rgba(107,114,128,.25);color:#cbd5e1}
.noc .q li.mt{opacity:.55}.noc .mtag{font-size:9px;font-weight:600;background:#374151;color:#cbd5e1;border-radius:3px;padding:0 5px;margin-left:4px}

.noc .dmore{font-size:10px;color:var(--mute);text-align:right;margin-top:1px}

/* --- frente do switch --- */
.noc .lgd{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px;font-size:10px;color:var(--ink2);margin-bottom:10px}
.noc .lgd .pt{width:14px;height:12px;cursor:default}
.noc .swc{background:#111827;border:1px solid var(--line);border-left:4px solid var(--ok);border-radius:6px;padding:10px 12px;margin-bottom:12px}
.noc .swc.warn{border-left-color:var(--warn)}.noc .swc.crit{border-left-color:var(--crit)}
.noc .swh{display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 16px;margin-bottom:10px}
.noc .swh b{font-size:15px}.noc .swh .kv{font-size:11px;color:var(--ink2)}.noc .swh .kv em{font:700 12px Consolas,monospace;color:var(--ink);font-style:normal}
.noc .swh .kv em.hot{color:#fca5a5}
.noc .chassis{margin-bottom:8px}
.noc .unit{font-size:10px;color:var(--mute);margin-bottom:2px}
.noc .face{display:flex;gap:12px;align-items:center;flex-wrap:wrap;overflow-x:auto;background:linear-gradient(180deg,#2a3140,#1c222e);border:1px solid #3a4456;border-radius:6px;padding:10px 14px;box-shadow:inset 0 1px 0 rgba(255,255,255,.06),0 2px 8px rgba(0,0,0,.4)}
.noc .swg{display:flex;flex-direction:column;gap:4px;flex:none;margin:0;padding:0;width:auto}
.noc .swg.upl{margin-left:auto;padding-left:14px;border-left:1px dashed #4b5568}
.noc .swr{display:flex;gap:4px;flex-wrap:nowrap;margin:0!important;padding:0;width:auto}
.noc .pt{flex:none;margin:0;box-sizing:border-box;position:relative;width:30px;height:24px;border-radius:3px;background:#0b0f17;border:1px solid #475569;display:flex;align-items:flex-end;justify-content:center;cursor:pointer}
.noc .pt span{font:9px Consolas,monospace;color:#94a3b8;line-height:1;margin-bottom:2px}
.noc .pt.rj::before{content:"";position:absolute;top:3px;left:50%;transform:translateX(-50%);width:12px;height:5px;border-radius:1px;background:currentColor;opacity:.9}
.noc .pt.sfp{width:36px;border-radius:2px}
.noc .pt.sfp::before{content:"";position:absolute;top:3px;left:5px;right:5px;height:6px;border:1px solid currentColor;border-radius:1px}
.noc .pt.up{color:#22c55e;border-color:#16a34a;background:#0d1f15}
.noc .pt.busy{color:#4ade80;border-color:#22c55e;background:#123a22;box-shadow:0 0 6px rgba(34,197,94,.45)}
.noc .pt.warm{color:#facc15;border-color:#f5b301;background:#2e2608}
.noc .pt.hot{color:#f87171;border-color:#ef4444;background:#3a1418;box-shadow:0 0 8px rgba(239,68,68,.55)}
.noc .pt.err{color:#fb923c;border-color:#fb923c;background:#2e1a0c}
.noc .pt.down,.noc .pt.unk{color:#334155;border-color:#334155}
.noc .pt:hover{outline:2px solid var(--accent);z-index:2}
.noc .swb{display:grid;grid-template-columns:1.4fr 1fr;gap:12px;margin-top:8px}
.noc .tp{display:grid;grid-template-columns:70px 1fr 90px 90px 40px;gap:6px;font-size:11px;padding:2px 0;border-bottom:1px solid var(--line);cursor:default}
.noc .tp span:nth-child(n+3){font-family:Consolas,monospace;text-align:right}.noc .tp .al{color:var(--mute);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
@media (max-width:1100px){.noc .swb{grid-template-columns:1fr}}

/* --- frota (equipamentos por ping) --- */
.noc .secs{display:flex;flex-direction:column;gap:10px;min-width:0}
.noc .sec{background:#111827;border:1px solid var(--line);border-left:4px solid var(--ok);border-radius:6px;padding:8px 10px}
.noc .sec.warn{border-left-color:var(--warn)}.noc .sec.crit{border-left-color:var(--crit)}.noc .sec.vazio{border-left-color:var(--mute);opacity:.7}
.noc .sh2{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:8px;font-size:13px}
.noc .sh2 .cnt{font:700 12px Consolas,monospace;color:var(--ink2)}
.noc .sh2 .cnt.crit{color:#fca5a5}.noc .sh2 .cnt.warn{color:#fcd34d}.noc .sh2 .cnt.ok{color:#86efac}
.noc .tag{font-size:10px;font-weight:700;padding:1px 6px;border-radius:3px}
.noc .tag.crit{background:rgba(239,68,68,.2);color:#fca5a5}.noc .tag.warn{background:rgba(245,179,1,.18);color:#fcd34d}
.noc .tag.unk{background:#1f2937;color:#94a3b8}.noc .tag.res{background:#1f2937;color:#94a3b8}
.noc .nota{font-size:10px;color:var(--mute);margin-left:auto}
.noc .tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(112px,1fr));gap:4px}
.noc .tl{display:flex;flex-direction:column;justify-content:center;min-height:34px;padding:3px 6px;border-radius:4px;background:#13261c;border:1px solid #1d3b2a;border-left:3px solid var(--ok);cursor:default;overflow:hidden}
.noc .tl .tn{font-size:11px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.noc .tl .tm{font:10px Consolas,monospace;color:var(--ink2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.noc .tl.warn{background:#2a2410;border-color:#4a3d10;border-left-color:var(--warn)}
.noc .tl.crit{background:#3a1418;border-color:#6b1d24;border-left-color:var(--crit);animation:nocblink 1.6s infinite}
.noc .tl.crit .tm{color:#fecaca;font-weight:700}
.noc .tl.unk{background:#151b26;border-color:#232c3b;border-left-color:var(--mute)}.noc .tl.unk .tn{color:#94a3b8}
.noc .tl.maint,.noc .tl.res{background:#141821;border-color:#1f2633;border-left-color:#475569;opacity:.55}
.noc .tl.mais{align-items:center;font-weight:700;color:var(--ink2);background:#151b26;border-left-color:var(--mute)}
.noc .tl:hover{outline:1px solid var(--accent)}
.noc .resumo{display:grid;grid-template-columns:repeat(auto-fill,minmax(360px,1fr));gap:10px}
.noc .rbar{height:8px;background:#1f2a3d;border-radius:4px;overflow:hidden;margin-bottom:8px}
.noc .rfill{height:100%;background:var(--ok)}.noc .rfill.warn{background:var(--warn)}.noc .rfill.crit{background:var(--crit)}
.noc .okmsg{grid-column:1/-1;color:#86efac;font-size:12px;padding:4px 0}
.noc .legend .lg{display:flex;flex-wrap:wrap;gap:4px;padding:8px 10px}.noc .legend .tl{min-height:22px;animation:none}
/* modo compacto (tela CFTV + acesso: centenas de equipamentos numa tela) */
.noc .compacto .tiles{grid-template-columns:repeat(auto-fill,minmax(66px,1fr));gap:3px}
.noc .compacto .tl{min-height:20px;padding:2px 5px;border-left-width:2px}
.noc .compacto .tl .tn{font-size:10px}
.noc .compacto .tl .tm{display:none}
.noc .compacto .tl.crit{animation:none}
.noc .compacto .tl.crit .tn{color:#fecaca}
.noc .compacto .sec{padding:6px 8px}.noc .compacto .sh2{margin-bottom:5px}
.noc .tl.crit.porta{background:repeating-linear-gradient(135deg,#3a1418 0 6px,#2a1014 6px 12px);border-style:dashed;border-left-style:solid}

/* --- links de internet --- */
.noc .lk-sum{display:flex;flex-wrap:wrap;align-items:center;gap:8px 14px;background:#111827;border:1px solid var(--line);border-left:6px solid var(--ok);border-radius:6px;padding:10px 14px;margin-bottom:12px}
.noc .lk-sum b{font-size:18px;color:#86efac}.noc .lk-sum span{font-size:12px;color:var(--ink2)}
.noc .lk-sum.warn{border-left-color:var(--warn)}.noc .lk-sum.warn b{color:#fcd34d}
.noc .lk-sum.crit{border-left-color:var(--crit);background:#1d1418}.noc .lk-sum.crit b{color:#fca5a5;animation:nocblink 1.6s infinite}
.noc .lk-sum .tag{font-size:11px}
.noc .lks{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:10px;margin-bottom:8px}
.noc .lk{background:#141c2b;border:1px solid var(--line);border-top:3px solid var(--ok);border-radius:6px;padding:10px 12px;display:flex;flex-direction:column;gap:8px;min-width:0}
.noc .lk.warn{border-top-color:var(--warn)}.noc .lk.crit{border-top-color:var(--crit);background:#1d1418}.noc .lk.unk{border-top-color:var(--mute);opacity:.75}
.noc .lk-h{display:flex;justify-content:space-between;align-items:flex-start;gap:8px}
.noc .lk-h b{font-size:16px;letter-spacing:.3px}.noc .lk-sub{font:10px Consolas,monospace;color:var(--mute);margin-top:2px}
.noc .lk-badge{font:700 10px/1 "Segoe UI",Arial;padding:4px 8px;border-radius:3px;background:#14532d;color:#bbf7d0;letter-spacing:.6px}
.noc .lk.warn .lk-badge{background:#4a3d10;color:#fde68a}.noc .lk.crit .lk-badge{background:#7f1d1d;color:#fecaca;animation:nocblink 1.6s infinite}.noc .lk.unk .lk-badge{background:#1f2937;color:#94a3b8}
.noc .lk-why{font-size:11px;color:#fcd34d}.noc .lk.crit .lk-why{color:#fca5a5;font-weight:600}
.noc .lk-dir{display:flex;flex-direction:column;gap:3px}
.noc .lk-dl{display:flex;align-items:baseline;gap:6px;font-size:11px;color:var(--ink2)}
.noc .lk-dl b{font:700 15px Consolas,monospace;color:var(--ink)}.noc .of{font:11px Consolas,monospace;color:var(--mute)}
.noc .lk-dl .pc{margin-left:auto;font:700 12px Consolas,monospace;color:var(--ink2)}.noc .pc.warn{color:#fcd34d}.noc .pc.crit{color:#fca5a5}
.noc .lk-bar{position:relative;height:8px;background:#1f2a3d;border-radius:4px;overflow:hidden}
.noc .lk-bar i{position:absolute;top:0;bottom:0;width:1px;background:rgba(255,255,255,.18)}
.noc .lk-fill{height:100%;border-radius:4px;background:#38bdf8}.noc .lk-fill.upl{background:#a78bfa}
.noc .lk-fill.warn{background:var(--warn)}.noc .lk-fill.crit{background:var(--crit)}
.noc .lk-spark{width:100%;height:56px;display:block;background:#0f1522;border-radius:4px}
.noc .lk-nospark{font-size:10px;color:var(--mute);padding:6px 0}
.noc .lk-ms{display:grid;grid-template-columns:repeat(5,1fr);gap:4px}
.noc .lk-m{background:#0f1522;border-radius:4px;padding:4px 6px;display:flex;flex-direction:column;min-width:0}
.noc .lk-m span{font-size:9px;color:var(--mute);text-transform:uppercase;letter-spacing:.5px}
.noc .lk-m b{font:700 13px Consolas,monospace;white-space:nowrap}.noc .lk-m em{font-size:9px;color:var(--mute);font-style:normal}
.noc .lk-m.warn b{color:#fcd34d}.noc .lk-m.crit b{color:#fca5a5}
.noc .lk-hint{font-size:10px;color:var(--ink2);background:#0f1522;border-left:2px solid var(--accent);padding:4px 6px;border-radius:2px}
.noc .lk-hint b{font-family:Consolas,monospace;color:var(--ink)}
.noc .lk-disc{margin-bottom:8px}.noc .lk-disc .tp{grid-template-columns:110px 1fr 90px 90px 40px}
.noc .lk-prs{margin-top:4px}
.noc .lk-leg{font-size:10px;color:var(--mute);margin-top:4px}
.noc .ifs{display:flex;flex-direction:column;gap:8px;margin:4px 0 8px}
.noc .ifg{background:#0f1522;border:1px solid var(--line);border-radius:6px;padding:6px 8px}
.noc .ifg.vpn{border-left:3px solid #a78bfa}
.noc .ifg-h{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 12px;font-size:11px;color:var(--ink2);margin-bottom:6px}
.noc .ifg-h b{font-size:12px;color:var(--ink);text-transform:uppercase;letter-spacing:.5px}
.noc .ifl{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:4px}
.noc .if{background:#141c2b;border:1px solid #1f2a3d;border-left:3px solid var(--ok);border-radius:4px;padding:4px 7px;min-width:0;cursor:default}
.noc .if:hover{outline:1px solid var(--accent)}
.noc .if-n{display:flex;align-items:center;gap:5px;min-width:0}
.noc .if-n i{flex:none;width:7px;height:7px;border-radius:50%;background:var(--ok)}
.noc .if-n b{font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.noc .if-a{font-size:10px;color:var(--mute);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.noc .if-t{font:10px Consolas,monospace;color:var(--ink2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.noc .if-t span{color:#c4b5fd}
.noc .if.busy{background:#12261c}.noc .if.busy .if-n i{box-shadow:0 0 5px #22c55e}
.noc .if.idle{border-left-color:#64748b}.noc .if.idle .if-n i{background:#94a3b8}
.noc .if.err{border-left-color:#fb923c}.noc .if.err .if-n i{background:#fb923c}
.noc .if.down{border-left-color:var(--crit);background:#1d1418}.noc .if.down .if-n i{background:var(--crit)}.noc .if.down .if-t{color:#fca5a5}
.noc .if.vazia,.noc .if.unk{border-left-color:#334155;opacity:.5}.noc .if.vazia .if-n i,.noc .if.unk .if-n i{background:#334155}
.noc .ifg.phys .if.down{background:#141c2b;opacity:.75}

.noc .lk-main{grid-template-columns:minmax(0,1fr) 340px;align-items:start}
.noc .lk-col{min-width:0}
.noc .lk-main .side{position:sticky;top:0}
.noc .lk-main .q{max-height:calc(100vh - 120px)}

/* --- modo compacto (faixa de links embutida em outra tela) --- */
.noc .lk-cmp .lk-sum{padding:6px 12px;margin-bottom:6px}.noc .lk-cmp .lk-sum b{font-size:15px}
.noc .lk-more{margin-left:auto;font-size:11px;color:#7dd3fc;text-decoration:none}.noc .lk-more:hover{text-decoration:underline}
.noc .lk-cmp .swc{padding:6px 10px;margin-bottom:0}.noc .lk-cmp .swh{margin-bottom:6px}
.noc .lk-cmp .lks{grid-template-columns:repeat(auto-fit,minmax(300px,440px));gap:8px;margin-bottom:6px}
.noc .lk-c{padding:6px 10px;gap:4px}.noc .lk-c .lk-h b{font-size:14px}.noc .lk-c .lk-sub{display:inline}
.noc .lk-c .lk-dl b{font-size:12px}.noc .lk-c .lk-bar{height:5px}.noc .lk-c .lk-why{font-size:10px}
.noc .lk-ci{font-size:10px;color:var(--mute)}.noc .lk-ci b{font:700 11px Consolas,monospace;color:var(--ink2)}.noc .lk-ci b.bad{color:#fca5a5}
.noc .ifc{display:flex;flex-wrap:wrap;align-items:center;gap:4px}
.noc .ifc-t{font-size:10px;color:var(--mute);text-transform:uppercase;letter-spacing:.5px;margin-right:4px}
.noc .ifx{display:inline-flex;align-items:center;gap:4px;font-size:10px;background:#141c2b;border:1px solid #1f2a3d;border-radius:10px;padding:1px 8px;cursor:default}
.noc .ifx i{width:6px;height:6px;border-radius:50%;background:var(--ok)}.noc .ifx em{font:9px Consolas,monospace;color:var(--mute);font-style:normal}
.noc .ifx.vpn{border-color:#4c3d7a}.noc .ifx.down{border-color:#7f1d1d;color:#fca5a5}.noc .ifx.down i{background:var(--crit)}
.noc .ifx.vazia,.noc .ifx.unk{opacity:.45}.noc .ifx.vazia i,.noc .ifx.unk i{background:#475569}
